def reconcile_windows(windows, blocked, minimum):
    merged = []
    for start, end in sorted(windows):
        if merged and start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    pieces = merged
    for cut_start, cut_end in blocked:
        updated = []
        for start, end in pieces:
            if cut_end <= start or cut_start >= end:
                updated.append([start, end])
            else:
                if start < cut_start:
                    updated.append([start, cut_start])
                if cut_end < end:
                    updated.append([cut_end, end])
        pieces = updated
    return [piece for piece in pieces if piece[1] - piece[0] >= minimum]

def session_summaries(events, gap):
