def eligible_shortest_route(nodes, edges, start, end, disabled):
    disabled_set = set(disabled)
    if start in disabled_set or end in disabled_set:
        return []
    graph = {node: [] for node in nodes}
    for left, right in edges:
        graph[left].append(right)
        graph[right].append(left)
    paths = [[start]]
    seen_depth = {start: 0}
    while paths:
        path = paths.pop(0)
        node = path[-1]
        if node == end:
            return path
        depth = len(path)
        for neighbor in sorted(graph[node]):
            if neighbor not in disabled_set and seen_depth.get(neighbor, depth) >= depth:
                seen_depth[neighbor] = depth
                paths.append(path + [neighbor])
    return []

